bool hasImage(LEDStripAnimation animation) {
    switch(animation) {
        case LEDStripAnimation::TestPattern: return true;
        case LEDStripAnimation::Heart: return true;
        case LEDStripAnimation::Rotorama: return true;
        default: return false;
    }
}

const uint32_t* getSectorPixels(LEDStripAnimation animation, uint16_t sector) {
    if(sector >= GENERATED_SECTOR_COUNT) return nullptr;

    switch(animation) {
        case LEDStripAnimation::TestPattern: return TestPatternPixels[sector];
        case LEDStripAnimation::Heart: return HeartPixels[sector];
        case LEDStripAnimation::Rotorama: return RotoramaPixels[sector];
        default: return nullptr;
    }
}
